//! Public policy used both before docker run and before every routed tool call.
use crate::config::Config;
use anyhow::{bail, ensure, Result};
use serde_json::Value;
use std::path::{Path, PathBuf};

pub const REBUILD_HINT: &str = "请调用 sandbox_start({projectDir:目标项目路径,rebuild:true}) 迁移；旧容器将停止并改名保留，不会删除。";

pub fn path_for_docker(path: &Path) -> String {
    let text = path.to_string_lossy();
    let text = text.trim_start_matches(r"\\?\");
    // Detect drive paths too, so Windows fixtures can be verified on Unix.
    if cfg!(windows) || (text.as_bytes().get(1) == Some(&b':') && text.as_bytes()[0].is_ascii_alphabetic()) {
        text.replace('\\', "/")
    } else { text.to_owned() }
}
fn forbidden_name(name: &str) -> bool {
    let name = name.to_ascii_lowercase();
    ["data", "claude-home", "sessions", "conversations", "providers.json", "collab.db", ".polaris", ".pi",
        ".claude", ".codex", ".ssh", ".aws", ".gnupg", ".kube"].contains(&name.as_str()) || name.ends_with(".key")
}
fn normalized(path: &Path) -> Result<PathBuf> {
    // Resolve existing ancestors even for currently absent protected directories.
    if path.exists() { return Ok(std::fs::canonicalize(path)?); }
    let parent = path.parent().ok_or_else(|| anyhow::anyhow!("SANDBOX_INVALID_PATH"))?;
    let name = path.file_name().ok_or_else(|| anyhow::anyhow!("SANDBOX_INVALID_PATH"))?;
    Ok(normalized(parent)?.join(name))
}
pub fn validate_source(source: &Path, protected: &[PathBuf]) -> Result<PathBuf> {
    ensure!(source.is_absolute(), "SANDBOX_UNSAFE_MOUNT: absolute path required; {REBUILD_HINT}");
    let source = std::fs::canonicalize(source)?;
    for path in protected {
        let path = normalized(path)?;
        ensure!(!source.starts_with(&path) && !path.starts_with(&source),
            "SANDBOX_UNSAFE_MOUNT: protected host data; {REBUILD_HINT}");
    }
    ensure!(!source.components().any(|p| forbidden_name(&p.as_os_str().to_string_lossy())),
        "SANDBOX_UNSAFE_MOUNT: forbidden path; {REBUILD_HINT}");
    ensure!(source.is_dir(), "SANDBOX_UNSAFE_MOUNT: directory required");
    // Binding a parent also exposes its children. Reject sensitive files anywhere in it.
    let mut pending = vec![source.clone()];
    while let Some(directory) = pending.pop() {
        for entry in std::fs::read_dir(directory)? {
            let entry = entry?;
            ensure!(!forbidden_name(&entry.file_name().to_string_lossy()),
                "SANDBOX_UNSAFE_MOUNT: directory contains protected files; {REBUILD_HINT}");
            // Symlinks cannot expose an unmounted host target inside the container.
            if entry.file_type()?.is_dir() { pending.push(entry.path()); }
        }
    }
    Ok(source)
}
#[derive(Debug)]
pub struct ResolvedMount { pub source: PathBuf, pub destination: String, pub read_only: bool }
impl Config {
    pub fn resolve_mounts(&self, project: &Path, kb: &Path, home: &Path) -> Result<Vec<ResolvedMount>> {
        self.validate()?;
        let protected = self.protected(home);
        let project = validate_source(project, &protected)?;
        let kb = validate_source(kb, &protected)?;
        ensure!(!project.starts_with(&kb) && !kb.starts_with(&project),
            "SANDBOX_UNSAFE_MOUNT: workspace and kb must not overlap");
        self.mounts.iter().map(|m| {
            let source = match m.source.as_str() {
                "${project}" => project.clone(), "${kb}" => kb.clone(),
                path => validate_source(Path::new(path), &protected)?,
            };
            let expected = if m.destination == "/workspace" { &project } else { &kb };
            ensure!(&source == expected, "SANDBOX_UNSAFE_MOUNT: source does not match requested root");
            Ok(ResolvedMount { source, destination: m.destination.clone(), read_only: m.read_only })
        }).collect()
    }
    pub fn run_args(&self, name: &str, image: &str, project: &Path, kb: &Path, home: &Path) -> Result<Vec<String>> {
        let mounts = self.resolve_mounts(project, kb, home)?;
        let mut args = vec!["run".into(), "-d".into(), "--name".into(), name.into(),
            format!("--memory={}", self.memory_bytes), format!("--cpus={}", self.cpus),
            "--cap-drop=ALL".into(), "--security-opt=no-new-privileges".into()];
        for capability in &self.cap_add { args.push(format!("--cap-add={capability}")); }
        for mount in mounts {
            let source = path_for_docker(&mount.source);
            ensure!(!source.contains([',', '\n', '\r']), "SANDBOX_INVALID_PATH: mount delimiter");
            args.push("--mount".into());
            args.push(format!("type=bind,src={source},dst={}{}", mount.destination,
                if mount.read_only { ",readonly" } else { "" }));
        }
        args.extend([image.into(), "sleep".into(), "infinity".into()]);
        Ok(args)
    }
    pub fn validate_container(&self, info: &Value, project: &Path, kb: &Path, home: &Path) -> Result<PathBuf> {
        let expected = self.resolve_mounts(project, kb, home)?;
        let mounts = info["Mounts"].as_array().ok_or_else(|| anyhow::anyhow!("SANDBOX_INVALID_MOUNTS"))?;
        // Check all sources first: legacy broad mounts always receive the migration diagnostic.
        for mount in mounts {
            ensure!(mount["Type"] == "bind", "SANDBOX_UNSAFE_MOUNT: unverified volume; {REBUILD_HINT}");
            let source = mount["Source"].as_str().ok_or_else(|| anyhow::anyhow!("SANDBOX_INVALID_MOUNTS"))?;
            validate_source(Path::new(source), &self.protected(home))?;
        }
        ensure!(mounts.len() == expected.len(), "SANDBOX_UNSAFE_MOUNT: unexpected mounts; {REBUILD_HINT}");
        let mut workdir_changed = false;
        for required in expected {
            let matching: Vec<_> = mounts.iter().filter(|m| m["Destination"] == required.destination).collect();
            ensure!(matching.len() == 1, "SANDBOX_UNSAFE_MOUNT: incorrect destination; {REBUILD_HINT}");
            let mount = matching[0];
            ensure!(mount["RW"].as_bool() == Some(!required.read_only),
                "SANDBOX_UNSAFE_MOUNT: incorrect access mode; {REBUILD_HINT}");
            let source = mount["Source"].as_str().ok_or_else(|| anyhow::anyhow!("SANDBOX_INVALID_MOUNTS"))?;
            if std::fs::canonicalize(source)? != required.source {
                if required.destination == "/workspace" { workdir_changed = true; }
                else { bail!("SANDBOX_UNSAFE_MOUNT: incorrect KB source; {REBUILD_HINT}"); }
            }
        }
        self.validate_security(info)?;
        ensure!(!workdir_changed, "SANDBOX_PATH_UNMOUNTED: work directory changed; {REBUILD_HINT}");
        Ok(std::fs::canonicalize(project)?)
    }
    pub fn validate_security(&self, info: &Value) -> Result<()> {
        let host = &info["HostConfig"];
        let memory = host["Memory"].as_u64().filter(|n| *n > 0 && *n <= self.memory_bytes).is_some();
        let cpu = host["NanoCpus"].as_u64().filter(|n| *n > 0 && *n <= (self.cpus * 1e9) as u64).is_some();
        let drop_all = host["CapDrop"].as_array().is_some_and(|a| a.iter().any(|v| v == "ALL"));
        let additions = host["CapAdd"].is_null() || host["CapAdd"].as_array().is_some_and(|a|
            a.iter().all(|v| v.as_str().is_some_and(|s| self.cap_add.iter().any(|c| c == s))));
        let no_new_privileges = host["SecurityOpt"].as_array().is_some_and(|a|
            a.iter().any(|v| v == "no-new-privileges" || v == "no-new-privileges:true"));
        ensure!(host["Privileged"] == false && host["PidMode"] != "host"
            && host["IpcMode"] != "host" && host["NetworkMode"] != "host"
            && host["Devices"].as_array().is_none_or(|a| a.is_empty())
            && memory && cpu && drop_all && additions && no_new_privileges,
            "SANDBOX_UNSAFE_CONTAINER: security baseline mismatch; {REBUILD_HINT}");
        Ok(())
    }
}
use crate::{config::{Config, WorkdirChange}, lifecycle::{decide, Action}, policy::path_for_docker};
use anyhow::Result;
use serde_json::{json, Value};
use std::path::{Path, PathBuf};
struct Fixture { root: PathBuf, home: PathBuf, project: PathBuf, kb: PathBuf }
impl Fixture {
    fn new() -> Result<Self> {
        let root = std::env::temp_dir().join(format!("p3b-{}-{}", std::process::id(),
            std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH)?.as_nanos()));
        let result = Self { home: root.join("home"), project: root.join("project"), kb: root.join("kb"), root };
        for path in [&result.home, &result.project, &result.kb] { std::fs::create_dir_all(path)?; }
        Ok(result)
    }
    fn inspect(&self) -> Value {
        json!({"Mounts":[
            {"Type":"bind","Source":self.project,"Destination":"/workspace","RW":true},
            {"Type":"bind","Source":self.kb,"Destination":"/kb","RW":false}],
            "HostConfig":{"Memory":4294967296u64,"NanoCpus":2000000000u64,"CapDrop":["ALL"],
                "CapAdd":null,"SecurityOpt":["no-new-privileges"],"Privileged":false,
                "PidMode":"","IpcMode":"private","NetworkMode":"bridge","Devices":[]}})
    }
    fn validate(&self, config: &Config, info: &Value) -> Result<PathBuf> {
        config.validate_container(info, &self.project, &self.kb, &self.home)
    }
}
impl Drop for Fixture { fn drop(&mut self) { let _ = std::fs::remove_dir_all(&self.root); } }
#[test]
fn run_mounts_only_project_and_readonly_kb() -> Result<()> {
    let f = Fixture::new()?;
    let c = Config::default();
    let args = c.run_args("test", "image", &f.project, &f.kb, &f.home)?;
    let text = args.join(" ");
    for forbidden in ["data/", ".key", "providers.json", "collab.db", "claude-home", "sessions"] {
        assert!(!text.contains(forbidden), "{text}");
    }
    assert_eq!(args.iter().filter(|a| *a == "--mount").count(), 2);
    assert!(text.contains("dst=/kb,readonly"));
    assert!(text.contains("--cap-drop=ALL --security-opt=no-new-privileges"));
    f.validate(&c, &f.inspect())?;
    Ok(())
}
#[test]
fn forbidden_config_and_parent_mounts_are_rejected() -> Result<()> {
    let f = Fixture::new()?;
    for suffix in ["Polaris/data", ".polaris", ".pi", ".claude", ".codex", ".ssh", ".aws", ".gnupg", ".kube",
        "Polaris/claude-home", "Polaris/sessions"] {
        let secret = f.home.join(suffix);
        std::fs::create_dir_all(&secret)?;
        let mut c = Config::default();
        c.mounts[0].source = secret.to_string_lossy().into_owned();
        assert!(c.run_args("test", "image", &f.project, &f.kb, &f.home).is_err());
        assert!(c.run_args("test", "image", &secret, &f.kb, &f.home).is_err());
    }
    let mut old = f.inspect();
    old["Mounts"][0]["Source"] = json!(f.home.join("Polaris"));
    assert!(f.validate(&Config::default(), &old).err().is_some_and(|e|
        e.to_string().contains("SANDBOX_UNSAFE_MOUNT") && e.to_string().contains("rebuild:true")));
    for name in ["host.key", "device.key", "providers.json", "collab.db"] {
        let secret = f.project.join(name);
        std::fs::write(&secret, "secret")?;
        assert!(f.validate(&Config::default(), &f.inspect()).is_err());
        let mut c = Config::default();
        c.mounts[0].source = secret.to_string_lossy().into_owned();
        assert!(c.run_args("test", "image", &f.project, &f.kb, &f.home).is_err());
        std::fs::remove_file(secret)?;
    }
    Ok(())
}
#[test]
fn rejects_wrong_destinations_modes_sources_and_extra_mounts() -> Result<()> {
    let f = Fixture::new()?;
    let c = Config::default();
    for (index, field, value) in [(0, "Destination", json!("/other")), (0, "RW", json!(false)),
        (1, "RW", json!(true)), (1, "Destination", json!("/workspace")), (1, "Type", json!("volume")),
        (1, "Source", json!(f.project))] {
        let mut info = f.inspect();
        info["Mounts"][index][field] = value;
        assert!(f.validate(&c, &info).is_err(), "{info}");
    }
    let mut info = f.inspect();
    if let Some(mounts) = info["Mounts"].as_array_mut() { mounts.push(json!({"Type":"bind","Source":f.home,"Destination":"/extra","RW":false})); }
    assert!(f.validate(&c, &info).is_err());
    let child = f.project.join("child");
    std::fs::create_dir(&child)?;
    assert!(c.validate_container(&f.inspect(), &child, &f.kb, &f.home).err()
        .is_some_and(|e| e.to_string().starts_with("SANDBOX_PATH_UNMOUNTED")));
    Ok(())
}
#[test]
fn rejects_missing_and_weakened_security_limits() -> Result<()> {
    let f = Fixture::new()?;
    let c = Config::default();
    for (key, value) in [("Memory", json!(0)), ("Memory", json!(8589934592u64)), ("NanoCpus", json!(0)),
        ("NanoCpus", json!(3000000000u64)), ("CapDrop", json!([])), ("CapAdd", json!(["SYS_ADMIN"])),
        ("SecurityOpt", json!([])), ("SecurityOpt", json!(["no-new-privileges:false"])),
        ("Privileged", json!(true)), ("PidMode", json!("host")), ("NetworkMode", json!("host")),
        ("Devices", json!([{"PathOnHost":"/dev/sda"}]))] {
        let mut info = f.inspect();
        info["HostConfig"][key] = value;
        assert!(f.validate(&c, &info).err().is_some_and(|e| e.to_string().contains("SANDBOX_UNSAFE_CONTAINER")));
    }
    let mut missing = f.inspect();
    missing["HostConfig"] = json!({});
    assert!(f.validate(&c, &missing).is_err());
    Ok(())
}
#[test]
fn config_types_defaults_and_append_only_protection() -> Result<()> {
    for input in [json!({"cpus":0}), json!({"memoryBytes":"4g"}), json!({"workdirChange":"delete"}),
        json!({"capAdd":["ALL"]}), json!({"mounts":[]}), json!({"unknown":true})] {
        assert!(serde_json::from_value::<Config>(input).and_then(|c|
            c.validate().map(|_| c).map_err(serde::de::Error::custom)).is_err());
    }
    let f = Fixture::new()?;
    let mut c: Config = serde_json::from_value(json!({"protectedPaths":[f.project]}))?;
    assert!(f.validate(&c, &f.inspect()).is_err());
    c.protected_paths.clear();
    assert!(c.protected(&f.home).contains(&f.home.join(".gnupg")));
    assert_eq!(c.memory_bytes, 4294967296);
    Ok(())
}
#[test]
fn lifecycle_never_automatically_migrates_unsafe_containers() -> Result<()> {
    let mut c = Config::default();
    assert_eq!(decide(None, &c, false)?, Action::Create);
    assert_eq!(decide(Some(Ok(PathBuf::from("project"))), &c, false)?, Action::Reuse);
    let changed = || Some(Err(anyhow::anyhow!("SANDBOX_PATH_UNMOUNTED: changed")));
    assert!(decide(changed(), &c, false).is_err());
    c.workdir_change = WorkdirChange::Rebuild;
    assert_eq!(decide(changed(), &c, false)?, Action::PreserveAndRebuild);
    for code in ["SANDBOX_UNSAFE_MOUNT", "SANDBOX_UNSAFE_CONTAINER"] {
        assert!(decide(Some(Err(anyhow::anyhow!(code))), &c, false).is_err());
        assert_eq!(decide(Some(Err(anyhow::anyhow!(code))), &c, true)?, Action::PreserveAndRebuild);
    }
    Ok(())
}
#[test]
fn windows_drive_paths_preserve_drive_and_spaces() {
    assert_eq!(path_for_docker(Path::new(r"D:\My Project\app")), "D:/My Project/app");
    assert_eq!(path_for_docker(Path::new(r"C:\项目")), "C:/项目");
    assert_eq!(path_for_docker(Path::new("E:/project")), "E:/project");
    assert_eq!(path_for_docker(Path::new(r"\\?\D:\project")), "D:/project");
}
#[cfg(unix)]
#[test]
fn symlink_alias_of_protected_source_is_rejected() -> Result<()> {
    let f = Fixture::new()?;
    let secret = f.home.join(".ssh");
    std::fs::create_dir(&secret)?;
    let alias = f.root.join("alias");
    std::os::unix::fs::symlink(secret, &alias)?;
    assert!(Config::default().run_args("test", "image", &alias, &f.kb, &f.home).is_err());
    Ok(())
}

#[test]
fn published_schema_defaults_match_runtime() -> Result<()> {
    let schema: Value = serde_json::from_str(include_str!("../sandbox.schema.json"))?;
    let defaults = serde_json::to_value(Config::default())?;
    if let Some(fields) = defaults.as_object() {
        for (key, value) in fields { assert_eq!(&schema["properties"][key]["default"], value, "{key}"); }
    } else { anyhow::bail!("config must be an object"); }
    Ok(())
}
