mod tests {
    use super::*;
    use super::super::super::config::Agentd;
    fn route() -> (Route, super::super::super::EventStream) {
        let (stream, receiver) = Mailbox::channel(4, 4096);
        let active = Arc::new(parking_lot::Mutex::new(std::collections::HashMap::from([("r".into(), "s".into())])));
        let reservations = Arc::new(parking_lot::Mutex::new(std::collections::HashSet::from(["s".into()])));
        (Route { req: "r".into(), session: "s".into(), active, acknowledged: true, started: false,
            reservation: (reservations, "s".into()), turn: None,
            translator: Translator::new("r".into(), None, "/tmp".into(), &Agentd::default()), stream,
            registered_at: Instant::now(), last_event_at: Instant::now(),
            idle_timeout: Duration::from_secs(240), max_duration: Duration::ZERO,
            abort_deadline: None, pending: VecDeque::new(), terminal: None, first_error: None }, receiver)
    }
    #[test]
    fn dropping_undrained_route_releases_active_and_reservation() {
        let (route, _receiver) = route();
        let active = route.active.clone();
        let reservations = route.reservation.0.clone();
        drop(route);
        assert!(active.lock().is_empty());
        assert!(reservations.lock().is_empty());
    }
    #[test]
    fn drop_finishes_full_unacknowledged_mailbox_and_preserves_finished_stream() -> anyhow::Result<()> {
        for finished in [false, true] {
            let (mut route, receiver) = route();
            route.acknowledged = false;
            for _ in 0..4 {
                assert!(route.stream.try_push(route.translator.make("tool", None)).is_ok());
            }
            if finished {
                route.stream.finish(None, route.translator.make("done", None));
            } else {
                route.fail("undrained failure");
            }
            drop(route);
            let wait = Duration::from_secs(1);
            for _ in 0..4 { assert_eq!(receiver.recv_timeout(wait)?.kind, "tool"); }
            if !finished {
                let error = receiver.recv_timeout(wait)?;
                assert_eq!(error.kind, "error");
                assert_eq!(error.text.as_deref(), Some(SUPERVISOR_EXITED));
            }
            assert_eq!(receiver.recv_timeout(wait)?.kind, "done");
            let closed = receiver.recv_timeout(wait).err().ok_or_else(|| anyhow::anyhow!("duplicate terminal"))?;
            assert!(matches!(closed.downcast_ref(), Some(super::super::super::stream::StreamError::Closed)));
        }
        Ok(())
    }
    #[test]
    fn first_failure_survives_abort_timeout() {
        for daemon_event in [false, true] {
            let (mut route, receiver) = route();
            if daemon_event {
                route.accept("t".into(), Event::Started).unwrap();
                route.accept("t".into(), Event::Error { code: "MODEL_ERROR".into(), message: "original".into() }).unwrap();
                route.accept("t".into(), Event::Completed { status: TurnStatus::Error }).unwrap();
            } else { route.fail("MODEL_ERROR: original"); }
            route.aborted();
            route.fail("AgentdAbortTimeout");
            assert!(route.drain());
            let error = receiver.recv_timeout(std::time::Duration::from_secs(1)).unwrap();
            assert_eq!(error.kind, "error");
            assert_eq!(error.text.as_deref(), Some("MODEL_ERROR: original"));
            assert_eq!(receiver.recv_timeout(std::time::Duration::from_secs(1)).unwrap().kind, "done");
        }
    }
    #[test]
    fn idle_budget_starts_at_registration_and_resets_on_hidden_events() -> anyhow::Result<()> {
        let (mut route, _receiver) = route();
        let idle = Duration::from_millis(300);
        route.idle_timeout = idle;
        let before_event = Instant::now() - idle * 5;
        route.registered_at = before_event;
        route.last_event_at = before_event;
        assert_eq!(route.timeout_error(Instant::now()), Some("AgentdTurnIdleTimeout"));
        route.accept("t".into(), Event::Started)?;
        route.accept("t".into(), Event::Reasoning { text: "working".into() })?;
        let last_event = route.last_event_at;
        assert_eq!(route.timeout_error(last_event + idle - Duration::from_millis(1)), None);
        assert_eq!(route.timeout_error(last_event + idle), Some("AgentdTurnIdleTimeout"));
        route.max_duration = idle * 2;
        assert_eq!(route.timeout_error(last_event), Some("AgentdTurnMaxTimeout"));
        route.accept("t".into(), Event::Completed { status: TurnStatus::Completed })?;
        assert_eq!(route.timeout_error(last_event + idle * 10), None);
        Ok(())
    }
}
//! Map Polaris keys to daemon UUIDs; never pass a conversation ID as a new UUID.
use super::{client::Client, protocol::{Command, Open, Session, Configure, SessionOptions}};
use super::super::TurnRequest;
use serde::{Serialize, Deserialize};
use serde_json::Value;
use sha2::{Digest, Sha256};
use std::path::PathBuf;
#[derive(Clone, Serialize, Deserialize)]
pub struct SessionInfo { pub id: String, pub cwd: PathBuf, pub model: Value, pub tools: Vec<String> }
fn path(client: &Client, key: &str) -> PathBuf {
    client.config.session_map.join(format!("{:x}.json", Sha256::digest(key.as_bytes())))
}
pub fn open(client: &Client, input: &TurnRequest, tools: super::super::ToolOptions) -> anyhow::Result<SessionInfo> {
    let mut options = super::input::options(client, input)?;
    options.sandbox = Some(tools.sandbox);
    options.expert_prompt = Some(tools.expert_prompt.unwrap_or_default());
    let file = path(client, &input.session_id);
    let previous: Option<SessionInfo> = match std::fs::read(&file) {
        Ok(bytes) => Some(serde_json::from_slice(&bytes)?),
        Err(e) if e.kind() == std::io::ErrorKind::NotFound => None,
        Err(e) => return Err(e.into()),
    };
    let cwd = std::fs::canonicalize(&input.cwd)?;
    let id = previous.as_ref().map(|s| s.id.clone());
    if let Some(previous) = &previous {
        if previous.cwd != cwd { let _ = client.call(Command::Close(Session { session_id: previous.id.clone() })); }
    }
    let response = client.call(Command::Open(Open { session_id: id, cwd: Some(cwd.to_string_lossy().into()), options: options.clone() }));
    let response = match response {
        Ok(v) => v,
        Err(e) if e.to_string().starts_with("SESSION_ALREADY_OPEN:") => {
            let previous = previous.as_ref().ok_or_else(|| anyhow::anyhow!("AgentdSessionMappingMissing"))?;
            client.call(Command::Configure(Configure { session_id: previous.id.clone(), options: options.clone() }))?
        }
        Err(e) if e.to_string().starts_with("SESSION_NOT_FOUND:") => {
            client.call(Command::Open(Open { session_id: None, cwd: Some(cwd.to_string_lossy().into()), options: options.clone() }))?
        }
        Err(e) => return Err(e),
    };
    anyhow::ensure!(response.get("reopenRequired") != Some(&Value::Bool(true)), "AgentdSessionReopenRequired");
    let info = SessionInfo {
        id: response.get("sessionId").and_then(Value::as_str).ok_or_else(|| anyhow::anyhow!("AgentdMissingSessionId"))?.into(),
        cwd, model: response.get("model").cloned().ok_or_else(|| anyhow::anyhow!("AgentdMissingModel"))?,
        tools: serde_json::from_value(response.get("tools").cloned().ok_or_else(|| anyhow::anyhow!("AgentdMissingTools"))?)?,
    };
    std::fs::create_dir_all(&client.config.session_map)?;
    let temporary = file.with_extension("tmp");
    std::fs::write(&temporary, serde_json::to_vec(&info)?)?;
    std::fs::rename(temporary, file)?;
    Ok(info)
}
pub fn close(client: &Client, key: &str) -> anyhow::Result<()> {
    let file = path(client, key);
    if !file.exists() { return Ok(()); }
    let info: SessionInfo = serde_json::from_slice(&std::fs::read(&file)?)?;
    match client.call(Command::Close(Session { session_id: info.id })) {
        Err(e) if !e.to_string().starts_with("SESSION_NOT_FOUND:") => Err(e),
        _ => Ok(()),
    }
}

/// The SDK is authoritative for busy detection; an active turn rejects configuration.
pub fn configure(client: &Client, key: &str, options: SessionOptions) -> anyhow::Result<Value> {
    let info: SessionInfo = serde_json::from_slice(&std::fs::read(path(client, key))?)?;
    client.call(Command::Configure(Configure { session_id: info.id, options }))
}
use super::*;
use super::protocol::{Event, Frame, TurnStatus};
use std::time::Instant;
pub(super) fn config() -> config::Agentd {
    static NEXT: std::sync::atomic::AtomicU64 = std::sync::atomic::AtomicU64::new(0);
    let mut c = config::Agentd::default();
    c.entry = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/fake-agentd.mjs");
    c.isolation = "shared".into();
    c.request_timeout_ms = 1500;
    c.turn_idle_timeout_ms = 3000;
    c.abort_timeout_ms = 100;
    c.restart_base_ms = 20;
    c.restart_max_ms = 80;
    c.restart_jitter_ms = 10;
    c.stable_reset_ms = 10000;
    c.failure_threshold = 3;
    c.max_line_bytes = 4096;
    c.channel_capacity = 2;
    c.session_map = std::env::temp_dir().join(format!("pi-tests-{}-{}", std::process::id(), NEXT.fetch_add(1, std::sync::atomic::Ordering::Relaxed)));
